import{_ as e,o as t,c as s,ag as o}from"./chunks/framework.CxkNbRKf.js";const g=JSON.parse('{"title":"Analytics reports","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/analytics-reports.md","filePath":"admin-guide/web-ui/analytics-reports.md","lastUpdated":1786379412000}'),i={name:"admin-guide/web-ui/analytics-reports.md"};function r(d,a,n,l,c,h){return t(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="analytics-reports" tabindex="-1">Analytics reports <a class="header-anchor" href="#analytics-reports" aria-label="Permalink to &quot;Analytics reports&quot;">​</a></h1><p>The analytics reports section provides statistics about catalog usage — pageviews, file downloads, top-viewed studies, and trends over time. This draws on events logged directly by NADA and is separate from external tools such as Google Analytics.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Analytics reports overview dashboard with KPI cards and 7-day chart</em></p></div><h2 id="accessing-analytics-reports" tabindex="-1">Accessing analytics reports <a class="header-anchor" href="#accessing-analytics-reports" aria-label="Permalink to &quot;Accessing analytics reports&quot;">​</a></h2><p>Go to <strong>Reports → Analytics reports</strong> in the administrator menu.</p><h2 id="overview-dashboard" tabindex="-1">Overview dashboard <a class="header-anchor" href="#overview-dashboard" aria-label="Permalink to &quot;Overview dashboard&quot;">​</a></h2><p>The overview shows key metrics at a glance:</p><ul><li>Today&#39;s pageviews and downloads</li><li>Monthly trend summary</li><li>Top studies by views</li><li>Top files by downloads</li><li>Recent activity feed</li><li>7-day view and download chart</li></ul><h2 id="raw-data" tabindex="-1">Raw data <a class="header-anchor" href="#raw-data" aria-label="Permalink to &quot;Raw data&quot;">​</a></h2><h3 id="pageviews" tabindex="-1">Pageviews <a class="header-anchor" href="#pageviews" aria-label="Permalink to &quot;Pageviews&quot;">​</a></h3><p>Individual page view events. Filter by date range or study ID. Data can be exported to CSV or JSON.</p><h3 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h3><p>Individual file download events with the same filter and export options.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Raw data tab showing pageviews with date filter applied</em></p></div><h2 id="aggregated-data" tabindex="-1">Aggregated data <a class="header-anchor" href="#aggregated-data" aria-label="Permalink to &quot;Aggregated data&quot;">​</a></h2><h3 id="daily" tabindex="-1">Daily <a class="header-anchor" href="#daily" aria-label="Permalink to &quot;Daily&quot;">​</a></h3><p>Day-by-day totals grouped by study or file. Use this view for a granular breakdown of activity.</p><h3 id="monthly" tabindex="-1">Monthly <a class="header-anchor" href="#monthly" aria-label="Permalink to &quot;Monthly&quot;">​</a></h3><p>Monthly summaries with trend charts for identifying longer-term patterns.</p><h2 id="aggregations" tabindex="-1">Aggregations <a class="header-anchor" href="#aggregations" aria-label="Permalink to &quot;Aggregations&quot;">​</a></h2><p>Raw events are processed through an aggregation pipeline to populate the daily and monthly views. Run aggregations periodically — for example, as a scheduled nightly task — to keep the data current.</p><table tabindex="0"><thead><tr><th>Step</th><th>What it does</th></tr></thead><tbody><tr><td>Daily</td><td>Aggregates raw events into daily totals (up to yesterday)</td></tr><tr><td>Monthly</td><td>Rolls daily totals into monthly summaries</td></tr><tr><td>Month-end</td><td>Finalizes past months and removes daily rows to save space</td></tr><tr><td>Cleanup</td><td>Deletes raw events older than 60 days</td></tr><tr><td>Sync</td><td>Updates view and download counters on catalog entries</td></tr></tbody></table><p>Click <strong>Run full aggregation</strong> to execute all steps, or run individual steps as needed.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Aggregation controls panel showing pipeline steps and last-run timestamp</em></p></div><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><p>For comprehensive web analytics (sessions, referrers, geographic breakdown), use an external tool such as Google Analytics. NADA&#39;s built-in analytics focuses on catalog-specific events — study views and file downloads.</p>',26)])])}const u=e(i,[["render",r]]);export{g as __pageData,u as default};
